/* cppi::50892fa8292836b3419abdf5232652954f837c9dea4123c14c9e5662706faab8 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-04-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-04-01'
    ) a
where arrival_time = max_publish

/* cppi::9706d523fead73b37daf428c5dc5aa2aec1604513ef65c1a291259393e93cc1a */
SELECT run_date, outcome, ruleset_id, run_timestamp, run_id, lookback_days, rule_id, evaluation_message, rule, rule_description, rule_name, rule_type, ruleset_version, run_account_id, evaluated_metrics, rule_dimension, database_name, table_name, failed_record_count, failed_percent, file_process_date, raised_exception, total_records_tested, total_pass_count, total_pass_percentage, completion_time, recheck, job_type, group_name, owner_name, frequency, data_source, dataset, dq_source, evaluated_rule
FROM dataops.dq_results where table_name LIKE '%ma%holding%lookthrough' order by file_process_date  desc limit 10

